#!/usr/bin/env node
/**
 * Tests for hooks/lib/sql-target.js, through hooks/guard-shell.js (its only caller). Zero
 * dependencies — `node:test` on Node 18+.
 *
 *   node --test "tools/*.test.mjs"
 *
 * Hermetic: the hook reads `devHosts` from `~/.claude/db-targets.json`, so every case runs with
 * HOME / USERPROFILE pointing at a temp directory holding a fixture registry, from an empty temp
 * cwd (the default-branch check can never answer).
 *
 * Generated by Claude Code at the user's request.
 */

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { spawnSync } from 'node:child_process';
import { mkdtempSync, mkdirSync, writeFileSync, readFileSync, rmSync } from 'node:fs';
import { join, dirname } from 'node:path';
import { tmpdir } from 'node:os';
import { fileURLToPath } from 'node:url';

const ROOT = join(dirname(fileURLToPath(import.meta.url)), '..');
const HOOK = join(ROOT, 'hooks', 'guard-shell.js');
const home = mkdtempSync(join(tmpdir(), 'sqltarget-home-'));
const cwd = mkdtempSync(join(tmpdir(), 'sqltarget-cwd-'));
mkdirSync(join(home, '.claude'));
writeFileSync(join(home, '.claude', 'db-targets.json'), JSON.stringify({
  devHosts: ['localhost', '127.0.0.1', 'host.docker.internal', 'postgres', 'redis'],
}));
process.on('exit', () => {
  for (const dir of [home, cwd]) { try { rmSync(dir, { recursive: true, force: true }); } catch { /* tmp */ } }
});

function run(command) {
  const env = { ...process.env, HOME: home, USERPROFILE: home };
  delete env.PGHOST;
  const r = spawnSync(process.execPath, [HOOK], {
    input: JSON.stringify({ tool_name: 'Bash', tool_input: { command }, cwd }), encoding: 'utf8', env,
  });
  assert.equal(r.status, 0, 'the hook must always exit 0');
  if (!r.stdout.trim()) return { decision: 'approve', reason: '' };
  const out = JSON.parse(r.stdout).hookSpecificOutput;
  return { decision: out.permissionDecision, reason: out.permissionDecisionReason ?? '' };
}

function expect(decision, commands, reasonPattern) {
  for (const command of commands) {
    const got = run(command);
    assert.equal(got.decision, decision, command);
    if (reasonPattern) assert.match(got.reason, reasonPattern, command);
  }
}

// ── SQL Server ─────────────────────────────────────────────────────────────────────────────────

test('sqlcmd: a dev host or no host passes, a named non-dev host is denied towards db-ro.ps1', () => {
  expect('approve', [
    'sqlcmd -S localhost,1433 -Q "SELECT 1"',
    'docker exec -i mssql sqlcmd -Q "SELECT 1"',
    'sqlcmd -Q "SELECT 1"',                       // no -S: the client's own local default
    'sqlcmd -d appdb -E -Q "SELECT 1"',
  ]);
  expect('deny', [
    'sqlcmd -S prod-sql.example.com -Q "SELECT 1"',
    'sqlcmd -S "" -Q "SELECT 1"',
    'sqlcmd -S $env:SQL_HOST -Q "SELECT 1"',
  ], /db-ro\.ps1/);
});

test('sqlcmd: LocalDB and the IPv6 loopback are local', () => {
  expect('approve', [
    'sqlcmd -S "(localdb)\\MSSQLLocalDB" -Q "SELECT 1"',
    'sqlcmd -S (localdb)\\MSSQLLocalDB -Q "SELECT 1"',
    'sqlcmd -S "tcp:[::1],1433" -Q "SELECT 1"',
    'sqlcmd -S ::1 -Q "SELECT 1"',
  ]);
  expect('deny', ['sqlcmd -S "tcp:[::2],1433" -Q "SELECT 1"'], /db-ro\.ps1/);
});

// ── Postgres ───────────────────────────────────────────────────────────────────────────────────

test('psql: the host comes from -h, --host, a URI or a conninfo', () => {
  expect('approve', [
    'psql -h localhost -U app -d appdb -c "select 1"',
    'psql --host=127.0.0.1 -At -c "select 1"',
    'psql "postgresql://app:pw@localhost:5432/appdb" -c "select 1"',
    'psql -d "host=localhost dbname=appdb" -c "select 1"',
    'pg_dump -h localhost -U app appdb',
  ]);
  expect('deny', [
    'psql -h pg-prod.example.com -U app -d appdb -c "select 1"',
    'psql --host=pg-prod.example.com -c "select 1"',
    'psql -hpg-prod.example.com -c "select 1"',
    'psql "postgres://app@example.net:5432/appdb" -c "select 1"',
    'psql postgresql://app@localhost,pg-prod.example.com/appdb',
    'psql -d "host=pg-prod.example.com dbname=appdb"',
    'psql "service=prod"',
    'pg_restore -h pg-prod.example.com -d appdb backup.dump',
    'pg_dumpall --host pg-prod.example.com',
    'psql -h $env:DB_HOST -c "select 1"',
  ], /db-ro\.ps1/);
});

test('psql: PGHOST on the line decides when no -h is given; no host at all is the local default', () => {
  expect('approve', [
    'PGHOST=localhost psql -c "select 1"',
    "$env:PGHOST='localhost'; psql -c 'select 1'",
    'psql -U app -d appdb -c "select 1"',
    'psql -d mydb -c "select 1"',
    'psql -h ::1 -d mydb -c "select 1"',
    'psql -h "[::1]" -d mydb -c "select 1"',
    'psql "postgresql://app@[::1]:5432/appdb" -c "select 1"',
  ]);
  expect('deny', [
    'PGHOST=pg-prod.example.com psql -c "select 1"',
    "$env:PGHOST = 'pg-prod.example.com'; psql -c 'select 1'",
    'export PGHOST=pg-prod.example.com && psql -c "select 1"',
    'PGSERVICE=prod psql -c "select 1"',
  ], /db-ro\.ps1/);
  // A value that only names a file or a SQL literal is not a host.
  expect('approve', ['psql -h localhost -c "select * from server where host=\'prod\'"']);
});

test('psql: --version and --help always pass', () => {
  expect('approve', ['psql --version', 'psql -V', 'redis-cli --version', 'pg_dump --help']);
});

// ── Redis ──────────────────────────────────────────────────────────────────────────────────────

test('redis-cli: host from -h or -u; none is 127.0.0.1', () => {
  expect('approve', [
    'redis-cli GET user:1',
    'redis-cli -h localhost -p 6379 -n 2 HGETALL session:42',
    'redis-cli -u redis://default:pw@localhost:6379/0 TTL k',
    'redis-cli -s /tmp/redis.sock INFO memory',
  ]);
  expect('deny', [
    'redis-cli -h cache-prod.example.com GET user:1',
    'redis-cli -u rediss://reader:pw@example.org:6380 GET user:1',
    'redis-cli --tls -h cache-prod.example.com -p 6380 PING',
  ], /db-ro\.ps1/);
});

test('redis-cli on a dev host: no allow-list, the owner writes to a local cache', () => {
  expect('approve', [
    'redis-cli SCAN 0 MATCH user:* COUNT 100',
    'redis-cli --scan --pattern "user:*"',
    'redis-cli SET a b',
    'redis-cli -h localhost -p 6379 DEL k',
    'redis-cli -h ::1 SET a b',
    'redis-cli KEYS "*"',
    'redis-cli',
    'Get-Content cmds.txt | redis-cli',
    'redis-cli --pipe',
  ]);
  // The one thing still asked is the flush, by destructive.js.
  expect('ask', ['redis-cli -h localhost -n 3 flushdb', 'docker exec -it redis redis-cli FLUSHALL'], /flushes/);
  // A non-dev host stays denied, whatever the command.
  expect('deny', ['redis-cli -h cache-prod.example.com SET a b', 'redis-cli -h cache-prod.example.com'], /db-ro\.ps1/);
});

// ── Wrappers: docker run|exec, wsl, shells ────────────────────────────────────────────────────

test('inside docker run|exec the client is found, and the container is its own default host', () => {
  expect('approve', [
    'docker compose exec -T postgres psql -U app -d appdb -c "select 1"',
    'docker exec -it redis redis-cli INFO memory',
    'docker run --rm -i --network app_default postgres:17 psql -h postgres -U app -c "select 1"',
    'docker run --rm -i postgres:17 psql -h host.docker.internal -p 5433 -U app -c "select 1"',
    'docker run --rm -i --name psql postgres:17 psql -h localhost -c "select 1"',
  ]);
  expect('deny', [
    'docker run --rm -i postgres:17 psql -h pg-prod.example.com -U app -c "select 1"',
    'docker run --rm -i -e PGHOST=pg-prod.example.com postgres:17 psql -c "select 1"',
    'docker run --rm -i -e PGHOST postgres:17 psql -c "select 1"',
    'docker run --rm -i redis:7 redis-cli --tls -h cache-prod.example.com GET k',
    'podman run --rm -i redis:7 redis-cli -h cache-prod.example.com GET k',
    'docker exec redis sh -c "redis-cli -h cache-prod.example.com GET k"',
    'docker exec redis bash -lc "redis-cli -h cache-prod.example.com GET k"',
  ]);
});

// ── A shell flag in any spelling still opens the command string ───────────────────────────────

test('a POSIX shell takes -c clustered with other options (-ec, -xc, -lic, -ce)', () => {
  const inner = '"psql -h pg-prod.example.com -c \'select 1\'"';
  expect('deny', [
    `bash -ec ${inner}`,
    `bash -xc ${inner}`,
    `sh -lic ${inner}`,
    `zsh -ce ${inner}`,
    `docker exec pg bash -ec ${inner}`,
    `wsl bash -ec ${inner}`,
  ], /db-ro\.ps1/);
  expect('approve', ['bash -ec "psql -h localhost -c \'select 1\'"', 'bash --login -c "ls"']);
});

test('PowerShell takes any abbreviation of -Command, found after its other options', () => {
  const inner = '"psql -h pg-prod.example.com -c \'select 1\'"';
  expect('deny', [
    `pwsh -Comm ${inner}`,
    `pwsh -Com ${inner}`,
    `pwsh -NoProfile -ExecutionPolicy Bypass -Command ${inner}`,
    `powershell.exe -NonInteractive -c ${inner}`,
    `pwsh -CommandWithArgs ${inner}`,
  ], /db-ro\.ps1/);
  expect('approve', ['pwsh -NoProfile -ExecutionPolicy Bypass -File build.ps1', 'pwsh -Comm "Get-Date"']);
});

test('cmd /c, /k and a --long option that merely contains a c', () => {
  expect('deny', ['cmd /c psql -h pg-prod.example.com -c "select 1"', 'cmd /s /k "psql -h pg-prod.example.com"'], /db-ro\.ps1/);
  expect('approve', ['bash --noprofile -c "ls"', 'docker exec pg bash --rcfile x -c "ls"']);
});

test('wsl is unwrapped, with or without -d, -e, --', () => {
  expect('approve', ['wsl redis-cli -h localhost GET k', 'wsl -d Ubuntu -- psql -h localhost -c "select 1"']);
  expect('deny', [
    'wsl redis-cli -h cache-prod.example.com GET k',
    'wsl -d Ubuntu -e psql -h pg-prod.example.com -c "select 1"',
    'wsl -- psql "postgresql://app@example.net/appdb"',
    'wsl bash -c "psql -h pg-prod.example.com -c \'select 1\'"',
  ], /db-ro\.ps1/);
  expect('approve', ['wsl sudo -u postgres psql -c "select 1"']); // no host: the local socket
});

test('a deny later on the line is still found', () => {
  expect('deny', ['redis-cli KEYS "*" && redis-cli -h cache-prod.example.com GET k'], /db-ro\.ps1/);
});

test('a tool only named, and db-ro.ps1 itself, pass', () => {
  expect('approve', [
    'which psql redis-cli',
    'wsl -e which psql redis-cli',
    'Get-Command psql, redis-cli -ErrorAction SilentlyContinue',
    'pwsh -NoProfile -File ~/.claude/scripts/db-ro.ps1 -Env prod -Query "SELECT 1"',
    'pwsh -NoProfile -File ~/.claude/scripts/db-ro.ps1 -Env prod -Query "SET k v"',
  ]);
});

test('the db-ro.ps1 allow rules match the one invocation form the agent documents, in both shells', () => {
  const agent = readFileSync(join(ROOT, 'agents', 'db-analyst.md'), 'utf8');
  const invocation = agent.match(/`(pwsh -NoProfile -File \S*db-ro\.ps1 [^`]*)`/)?.[1];
  assert.ok(invocation, 'agents/db-analyst.md documents a db-ro.ps1 invocation');
  const { allow } = JSON.parse(readFileSync(join(ROOT, 'settings.json'), 'utf8')).permissions;
  const toRegExp = (glob) => new RegExp(`^${glob.replace(/[.+?^${}()|[\]\\]/g, '\\$&').replace(/\*/g, '.*')}$`);
  for (const tool of ['Bash', 'PowerShell']) {
    const globs = allow.filter((r) => r.startsWith(`${tool}(`) && r.includes('db-ro.ps1')).map((r) => r.slice(tool.length + 1, -1));
    assert.ok(globs.length, `${tool} has a db-ro.ps1 allow rule`);
    assert.ok(globs.some((g) => toRegExp(g).test(invocation)), `${tool}: no allow rule matches "${invocation}"`);
  }
});
